#include <stdio.h>
int main(void) {
    int n = 2;
    switch (n) {
        case 1: printf("One ");
        case 2: printf("Two ");
        case 3: printf("Three ");
        default: printf("Default");
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int a = 5, b = 10, c = 15;
    if (a > b) {
        if (b > c) {
            printf("A\n");
        } else {
            printf("B\n");
        }
    } else {
        printf("C\n");
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int x = 5;
    if (x < 0) {
        printf("Negative\n");
    } else if (x == 0) {
        printf("Zero\n");
    } else if (x < 10) {
        printf("Small\n");
    } else {
        printf("Large\n");
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int a = 7, b = 3;
    int max;
    if (a > b) {
        max = a;
    } else {
        max = b;
    }
    printf("%d\n", max);
    return 0;
}

#include <stdio.h>
int main(void) {
    int i;
    for (i = 0; i < 5; i++) {
        if (i == 2) {
            continue;
        }
        printf("%d ", i);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    char c = 'x';
    switch (c) {
        case 'a': printf("A\n"); break;
        case 'b': printf("B\n"); break;
        default: printf("Other\n"); break;
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int a = 1, b = 0;
    if (a == 1)
        if (b == 1)
            printf("X\n");
    else
        printf("Y\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int i, j;
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            if (i + j == 2) {
                break;
            }
            printf("%d ", i + j);
        }
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
int main(void) {
    int x = 10, y = 5;
    if (x > 5 && y < 10) {
        if (x % y == 0) {
            printf("A\n");
        } else {
            printf("B\n");
        }
    } else {
        printf("C\n");
    }
    return 0;
}

#include <stdio.h>
int main(void) {
    int n = 6;
    switch (n) {
        case 1: case 3: case 5:
            printf("Odd\n");
            break;
        case 2: case 4: case 6:
            printf("Even\n");
            break;
        default:
            printf("Other\n");
    }
    return 0;
}
